/** Real authority transactions. Fixture ACTIVE metadata is not remote rollout or membership-protocol acceptance. */
class ClusterDeploymentFenceIT {
 static final GenericContainer<?> PG=IsolatedContainers.postgres("deployment-fence");
 @BeforeAll static void start(){PG.start();}@AfterAll static void stop(){PG.stop();}
 @TempDir Path root;EventFoundationTestSupport.Database db;UUID cluster;ClusterMember campus;ClusterControlLease first,standby;ClusterStore membership;DeploymentExecutor executor,other;ClusterDeploymentFence fence,second;String fp;ControlProperties settings;ClusterControlHandoff firstHandoff,secondHandoff;final String manifest="a".repeat(64);
 @BeforeEach void setup(){cluster=UUID.randomUUID();campus=new ClusterMember("campus",UUID.randomUUID(),"CAMPUS",0);var site=new SiteProperties();site.setMode(SiteProperties.Mode.CAMPUS);site.setId(campus.siteId());site.setInstanceId(campus.instanceId());site.setClusterId(cluster);site.setAllocationSlot(0);db=EventFoundationTestSupport.createDatabase(PG,site);String role="\""+db.runtimeUsername()+"\"";db.admin().execute("GRANT USAGE ON SCHEMA eatwhat_cluster TO "+role);db.admin().execute("GRANT SELECT,INSERT,UPDATE ON ALL TABLES IN SCHEMA eatwhat_cluster TO "+role);db.admin().execute("GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA eatwhat_cluster TO "+role);first=new ClusterControlLease(db.runtime(),cluster,5);standby=new ClusterControlLease(db.runtime(),cluster,5);membership=new ClusterStore(db.runtime(),db.transactions(),cluster,campus.identity(),first);membership.initialize();settings=new ControlProperties();var audit=new ControlAudit(root.resolve("shared"));executor=new DeploymentExecutor(settings,audit);other=new DeploymentExecutor(settings,audit);firstHandoff=new ClusterControlHandoff(db.runtime(),db.transactions(),first,executor,"first");secondHandoff=new ClusterControlHandoff(db.runtime(),db.transactions(),standby,other,"standby");assertTrue(first.tick());assertFalse(standby.tick());fp=db.admin().queryForObject("SELECT md5(cluster_identifier||':'||database_oid::text) FROM eatwhat_identity.node_state WHERE singleton",String.class);db.admin().update("UPDATE eatwhat_cluster.state SET epoch=1 WHERE singleton");db.admin().update("INSERT INTO eatwhat_cluster.member(site_id,instance_id,profile_id,mode,allocation_slot,state,database_fingerprint,joined_epoch) VALUES(?,?,'campus','CAMPUS',0,'ACTIVE',?,1)",campus.siteId(),campus.instanceId(),fp);fence=new ClusterDeploymentFence(db.runtime(),db.transactions(),first,executor.stateIdentity());second=new ClusterDeploymentFence(db.runtime(),db.transactions(),standby,other.stateIdentity());}
 List<ClusterDeploymentFence.Binding> bindings(){return List.of(new ClusterDeploymentFence.Binding(campus.siteId(),campus.instanceId(),fp));}
 @Test void recoveryRequiresAHeldLeaseAndAuthorizedOriginalFenceWhileTerminalStatusRemainsReadable(){UUID id=UUID.randomUUID();fence.reserve(id,manifest,1,bindings());assertEquals("DEPLOYMENT_DISPATCH_NOT_AUTHORIZED",assertThrows(ClusterFailure.class,()->fence.requireRecovery(id,manifest,true)).getMessage());fence.authorizeDispatch(id,manifest);assertDoesNotThrow(()->fence.requireRecovery(id,manifest,true));assertThrows(ClusterFailure.class,()->second.requireRecovery(id,manifest,true));assertEquals("DEPLOYMENT_FENCE_MANIFEST_CHANGED",assertThrows(ClusterFailure.class,()->fence.requireRecovery(id,"b".repeat(64),true)).getMessage());secondHandoff.request("operator",UUID.randomUUID(),1,UUID.fromString(standby.status().get("localControllerId").toString()));assertTrue(first.draining());assertEquals("CONTROL_HANDOFF_PENDING",assertThrows(ClusterFailure.class,first::requireAccepting).getMessage());assertDoesNotThrow(()->fence.requireRecovery(id,manifest,true));fence.finish(id,manifest,"FAILED",false);assertDoesNotThrow(()->fence.requireRecovery(id,manifest,false));assertEquals("DEPLOYMENT_FENCE_NOT_ACTIVE",assertThrows(ClusterFailure.class,()->fence.requireRecovery(id,manifest,true)).getMessage());}
 ClusterMember external(){return new ClusterMember("external",UUID.randomUUID(),"EXTERNAL",1);}
 @AfterEach void close(){if(executor!=null)executor.close();if(other!=null)other.close();}
 @Test void activeFenceIsDurableIdempotentAndSerializesNewMembershipCommands(){UUID job=UUID.randomUUID();fence.reserve(job,manifest,1,bindings());fence.reserve(job,manifest,1,bindings());assertEquals(1,fence.active().size());assertEquals("ACTIVE",fence.verify(job,manifest,false).get("state"));assertEquals("DEPLOYMENT_ACTIVE",assertThrows(ClusterFailure.class,()->membership.register("operator",UUID.randomUUID(),1,"external",external())).getMessage());assertEquals("DEPLOYMENT_RECONCILIATION_REQUIRED",assertThrows(ClusterFailure.class,()->fence.reserve(UUID.randomUUID(),manifest,1,bindings())).getMessage());fence.finish(job,manifest,"FAILED",false);assertTrue(fence.finalized(job,manifest,"FAILED"));assertTrue(fence.active().isEmpty());assertEquals("REGISTERED",membership.register("operator",UUID.randomUUID(),1,"external",external()).get("state"));assertEquals(1L,db.admin().queryForObject("SELECT count(*) FROM eatwhat_cluster.deployment_fence",Long.class));}
 @Test void leaseTakeoverDoesNotExpireOrIgnoreAnUnresolvedRemoteRelease(){UUID job=UUID.randomUUID();fence.reserve(job,manifest,1,bindings());fence.authorizeDispatch(job,manifest);db.admin().update("UPDATE eatwhat_cluster.deployment_fence SET created_at=clock_timestamp()-interval '30 days' WHERE job_id=?",job);first.release();assertTrue(standby.tick());assertEquals("CONTROL_LEASE_NOT_HELD",assertThrows(ClusterFailure.class,()->fence.finish(job,manifest,"SUCCEEDED",false)).getMessage());assertEquals("ACTIVE",second.verify(job,manifest,true).get("state"));assertEquals("DEPLOYMENT_RECONCILIATION_REQUIRED",assertThrows(ClusterFailure.class,()->second.reserve(UUID.randomUUID(),manifest,1,bindings())).getMessage());var newStore=new ClusterStore(db.runtime(),db.transactions(),cluster,campus.identity(),standby);assertEquals("DEPLOYMENT_ACTIVE",assertThrows(ClusterFailure.class,()->newStore.register("operator",UUID.randomUUID(),1,"external",external())).getMessage());second.finish(job,manifest,"SUCCEEDED",false);assertTrue(second.finalized(job,manifest,"SUCCEEDED"));}
 @Test void differentStateManifestAndDatabaseIdentityCannotAuthorizeOrFinalizeARelease(){UUID job=UUID.randomUUID();fence.reserve(job,manifest,1,bindings());assertEquals("DEPLOYMENT_FENCE_MANIFEST_CHANGED",assertThrows(ClusterFailure.class,()->fence.verify(job,"b".repeat(64),true)).getMessage());var foreign=new ClusterDeploymentFence(db.runtime(),db.transactions(),first,UUID.randomUUID());assertEquals("CONTROL_SHARED_STATE_REQUIRED",assertThrows(ClusterFailure.class,()->foreign.verify(job,manifest,false)).getMessage());assertEquals("CONTROL_SHARED_STATE_REQUIRED",assertThrows(ClusterFailure.class,()->foreign.finish(job,manifest,"SUCCEEDED",false)).getMessage());fence.finish(job,manifest,"FAILED",false);assertEquals("DEPLOYMENT_TARGET_IDENTITY_CHANGED",assertThrows(ClusterFailure.class,()->fence.reserve(UUID.randomUUID(),manifest,1,List.of(new ClusterDeploymentFence.Binding(campus.siteId(),campus.instanceId(),"b".repeat(32))))).getMessage());}
 @Test void staleEpochAndPendingMembershipCannotReserveAPublication(){assertEquals("STALE_MEMBERSHIP_EPOCH",assertThrows(ClusterFailure.class,()->fence.reserve(UUID.randomUUID(),manifest,2,bindings())).getMessage());var target=external();membership.register("operator",UUID.randomUUID(),1,"external",target);membership.begin("operator",UUID.randomUUID(),1,"JOIN",target.siteId(),"b".repeat(32));assertEquals("MEMBERSHIP_CHANGE_PENDING",assertThrows(ClusterFailure.class,()->fence.reserve(UUID.randomUUID(),manifest,1,bindings())).getMessage());assertEquals(0L,db.admin().queryForObject("SELECT count(*) FROM eatwhat_cluster.deployment_fence",Long.class));}
 @Test void releaseAdmissionWaitsForAnInFlightMemberChangeAndThenObservesItsDecision()throws Exception{var entered=new CountDownLatch(1);var finish=new CountDownLatch(1);try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var mutation=pool.submit(()->first.write(db.transactions(),()->{db.runtime().queryForList("SELECT epoch FROM eatwhat_cluster.state WHERE singleton FOR UPDATE");entered.countDown();try{assertTrue(finish.await(10,TimeUnit.SECONDS));}catch(InterruptedException e){throw new IllegalStateException(e);}var target=external();membership.register("operator",UUID.randomUUID(),1,"external",target);membership.begin("operator",UUID.randomUUID(),1,"JOIN",target.siteId(),"b".repeat(32));return true;}));assertTrue(entered.await(3,TimeUnit.SECONDS));var admission=pool.submit(()->{fence.reserve(UUID.randomUUID(),manifest,1,bindings());return true;});assertThrows(TimeoutException.class,()->admission.get(250,TimeUnit.MILLISECONDS));finish.countDown();assertTrue(mutation.get(5,TimeUnit.SECONDS));var failure=assertThrows(ExecutionException.class,()->admission.get(5,TimeUnit.SECONDS));assertInstanceOf(ClusterFailure.class,failure.getCause());assertEquals("MEMBERSHIP_CHANGE_PENDING",failure.getCause().getMessage());}finally{finish.countDown();}}
 @Test void terminalFenceCannotBeReactivatedOrHaveItsKnownOutcomeRewritten(){UUID job=UUID.randomUUID();fence.reserve(job,manifest,1,bindings());fence.authorizeDispatch(job,manifest);fence.finish(job,manifest,"PARTIAL_FAILURE",false);fence.finish(job,manifest,"PARTIAL_FAILURE",false);assertEquals("DEPLOYMENT_FENCE_NOT_ACTIVE",assertThrows(ClusterFailure.class,()->fence.verify(job,manifest,true)).getMessage());assertEquals("DEPLOYMENT_FENCE_IDEMPOTENCY_CONFLICT",assertThrows(ClusterFailure.class,()->fence.reserve(job,manifest,1,bindings())).getMessage());assertEquals("DEPLOYMENT_FENCE_OUTCOME_CONFLICT",assertThrows(ClusterFailure.class,()->fence.finish(job,manifest,"SUCCEEDED",false)).getMessage());assertEquals("DEPLOYMENT_FENCE_NOT_FOUND",assertThrows(ClusterFailure.class,()->fence.finish(UUID.randomUUID(),manifest,"FAILED",false)).getMessage());fence.finish(UUID.randomUUID(),manifest,"FAILED",true);}
 @Test void databaseGuardsAlsoBlockLegacySqlButPermitStartupForReadOnlyReconciliation(){UUID job=UUID.randomUUID();fence.reserve(job,manifest,1,bindings());assertThrows(org.springframework.dao.DataAccessException.class,()->db.admin().update("UPDATE eatwhat_cluster.state SET epoch=2 WHERE singleton"));assertThrows(org.springframework.dao.DataAccessException.class,()->db.admin().update("UPDATE eatwhat_cluster.member SET state='RETIRED' WHERE site_id='campus'"));new ClusterStore(db.runtime(),db.transactions(),cluster,campus.identity(),first).initialize();assertEquals(1,((Number)membership.status().get("epoch")).intValue());UUID target=UUID.fromString(standby.status().get("localControllerId").toString());assertThrows(org.springframework.dao.DataAccessException.class,()->db.admin().update("UPDATE eatwhat_cluster.control_lease SET holder_id=?,generation=generation+1 WHERE singleton",target));UUID legacy=UUID.randomUUID();db.admin().update("INSERT INTO eatwhat_cluster.control_process(holder_id,cluster_id,name,state_id,lease_seconds,expires_at) VALUES(?,?,'legacy',?,5,clock_timestamp()+interval '5 seconds')",legacy,cluster,executor.stateIdentity());first.release();var denied=assertThrows(org.springframework.dao.DataAccessException.class,()->db.admin().update("UPDATE eatwhat_cluster.control_lease SET holder_id=?,generation=generation+1 WHERE singleton",legacy));assertTrue(denied.getMessage().contains("DEPLOYMENT_PROTOCOL_REQUIRED"));assertTrue(standby.tick());assertEquals("ACTIVE",fence.verify(job,manifest,false).get("state"));}
 @Test void realWorkerLostAcknowledgementSurvivesTakeoverAndOnlyReadOnlyReconciliationReleasesTheFence()throws Exception{
  settings.getDeployment().setTargetSource(ControlProperties.Deployment.TargetSource.REGISTERED_SERVERS);settings.getDeployment().setEnabled(true);Path artifact=root.resolve("candidate.jar");Files.writeString(artifact,"synthetic isolated release artifact");String digest=DeploymentExecutor.artifactSha(artifact);var release=new ControlProperties.Release();release.setArtifact(artifact);release.setSha256(digest);release.setAcceptanceEvidenceId("synthetic-reviewed");release.setRollbackCompatible(true);release.setCompatibleFromSha256(List.of("a".repeat(64)));settings.getReleases().put("candidate",release);UUID server=UUID.randomUUID();var applied=new java.util.concurrent.atomic.AtomicInteger();var authority=new java.util.concurrent.atomic.AtomicReference<>(fence);
  // Only remote receipts are simulated here; both workers, journals, leases,
  // membership writes and authority fence transactions are actual implementations.
  var transport=new DeploymentExecutor.RegisteredTransport(){
   public boolean available(){return true;}
   public ControlProperties.DeploymentTarget resolve(DeploymentExecutor.Target expected){var t=new ControlProperties.DeploymentTarget();t.setSiteId(campus.siteId());t.setInstanceId(campus.instanceId());t.setServerId(server);t.setServerRevision(1);t.setClusterId(cluster);t.setMembershipEpoch(1);t.setDatabaseFingerprint(fp);t.setHost("fixture.invalid");t.setUser("root");t.setCurrentSha256("a".repeat(64));t.setRestoreEvidenceId("synthetic-reviewed");t.setEncryptedConnection("synthetic-private-binding");return t;}
   public void reserve(UUID id,String hash,List<ControlProperties.DeploymentTarget> t){assertTrue(authority.get().reserve(id,hash,1,bindings()));authority.get().authorizeDispatch(id,hash);}
   public void verifyReservation(UUID id,String hash,boolean applying){authority.get().verify(id,hash,applying);}
   public void complete(UUID id,String hash,Map<String,Object> job){authority.get().finish(id,hash,job.get("state").toString(),false);}
   public boolean finalized(UUID id,String hash,Map<String,Object> job){return authority.get().finalized(id,hash,job.get("state").toString());}
   public Map<String,Object> call(String action,UUID id,ControlProperties.DeploymentTarget t,Path file,String sha)throws Exception{if(action.equals("apply")){applied.incrementAndGet();throw new java.io.IOException("Lost remote acknowledgement");}return Map.of("id",id.toString(),"siteId",campus.siteId(),"instanceId",campus.instanceId().toString(),"artifactSha256",sha,"state",action.equals("prepare")?"PREPARED":"SUCCEEDED");}
  };
  executor.registeredTransport(transport);other.registeredTransport(transport);executor.externalIdleGuard(()->fence.active().isEmpty()?null:"DEPLOYMENT_RECONCILIATION_REQUIRED");other.externalIdleGuard(()->second.active().isEmpty()?null:"DEPLOYMENT_RECONCILIATION_REQUIRED");UUID job=UUID.randomUUID();executor.execute("operator",job,"candidate",digest,List.of(new DeploymentExecutor.Target(campus.siteId(),campus.siteId(),campus.instanceId())),first::requireHeld);long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(5);while(System.nanoTime()<end&&!"OUTCOME_UNKNOWN".equals(executor.get(job).get("state")))Thread.sleep(10);assertEquals("OUTCOME_UNKNOWN",executor.get(job).get("state"));assertEquals(1,applied.get());String hash=fence.active().getFirst().get("manifest_hash").toString();UUID transfer=UUID.randomUUID();secondHandoff.request("operator",transfer,1,UUID.fromString(standby.status().get("localControllerId").toString()));first.tick();assertEquals("DEPLOYMENT_RECONCILIATION_REQUIRED",firstHandoff.get(transfer).get("reason"));first.release();assertTrue(standby.tick());assertEquals("FAILED",firstHandoff.get(transfer).get("state"));assertEquals("ACTIVE",second.verify(job,hash,true).get("state"));authority.set(second);assertEquals("SUCCEEDED",other.reconcile("operator",job).get("state"));assertEquals(1,applied.get());assertTrue(second.finalized(job,hash,"SUCCEEDED"));var current=new ClusterStore(db.runtime(),db.transactions(),cluster,campus.identity(),standby);assertEquals("REGISTERED",current.register("operator",UUID.randomUUID(),1,"external",external()).get("state"));
 }
 @Test void missingLocalJournalDoesNotMakeAnActiveAuthorityFenceDisappear(){UUID job=UUID.randomUUID();fence.reserve(job,manifest,1,bindings());executor.externalIdleGuard(()->fence.active().isEmpty()?null:"DEPLOYMENT_RECONCILIATION_REQUIRED");assertEquals("DEPLOYMENT_RECONCILIATION_REQUIRED",executor.whenIdle(()->fail("Lost local journals must not permit new effects")));assertEquals("DEPLOYMENT_RECONCILIATION_REQUIRED",assertThrows(ClusterFailure.class,first::requireAccepting).getMessage());assertEquals(job.toString(),fence.active().getFirst().get("job_id"));}
 @Test void positiveNoDispatchProofIsLostPermanentlyOnceTheAuthorityAuthorizesEffects(){UUID job=UUID.randomUUID();assertTrue(fence.reserve(job,manifest,1,bindings()));assertFalse(fence.reserve(job,manifest,1,bindings()));assertTrue(fence.noDispatchProven(job,manifest));assertEquals("DEPLOYMENT_DISPATCH_NOT_AUTHORIZED",assertThrows(ClusterFailure.class,()->fence.verify(job,manifest,true)).getMessage());assertEquals("DEPLOYMENT_DISPATCH_NOT_AUTHORIZED",assertThrows(ClusterFailure.class,()->fence.finish(job,manifest,"SUCCEEDED",false)).getMessage());fence.authorizeDispatch(job,manifest);assertFalse(fence.noDispatchProven(job,manifest));assertEquals("ACTIVE",fence.verify(job,manifest,true).get("state"));assertEquals("DEPLOYMENT_RECONCILIATION_REQUIRED",assertThrows(ClusterFailure.class,()->fence.authorizeDispatch(job,manifest)).getMessage());fence.finish(job,manifest,"FAILED",false);assertFalse(fence.noDispatchProven(job,manifest));}
 @Test void scopedCallbackRequiresTheOriginalCapabilityAndCannotAuthorizeATerminalRelease(){
  UUID job=UUID.randomUUID();String token="x".repeat(43),hash=ClusterDeploymentFence.tokenHash(token);assertTrue(fence.reserve(job,manifest,1,bindings(),hash));
  var pending=fence.callback(job,manifest,token);assertEquals(false,pending.get("authorized"));assertEquals(false,pending.get("dispatchAuthorized"));
  for(String bad:Arrays.asList(null,"x","y".repeat(43),"x".repeat(44)))assertEquals("DEPLOYMENT_CALLBACK_AUTHENTICATION_REQUIRED",assertThrows(ControlFailure.class,()->fence.callback(job,manifest,bad)).code);
  assertEquals("DEPLOYMENT_CALLBACK_AUTHENTICATION_REQUIRED",assertThrows(ControlFailure.class,()->fence.callback(UUID.randomUUID(),manifest,token)).code);
  assertEquals("DEPLOYMENT_FENCE_MANIFEST_CHANGED",assertThrows(ClusterFailure.class,()->fence.callback(job,"b".repeat(64),token)).getMessage());
  assertEquals("DEPLOYMENT_FENCE_IDEMPOTENCY_CONFLICT",assertThrows(ClusterFailure.class,()->fence.reserve(job,manifest,1,bindings(),ClusterDeploymentFence.tokenHash("y".repeat(43)))).getMessage());
  fence.authorizeDispatch(job,manifest);var active=fence.callback(job,manifest,token);assertEquals(true,active.get("authorized"));assertEquals(bindings(),active.get("targets"));assertFalse(active.toString().contains(token));assertFalse(active.toString().contains(hash));
  first.release();assertTrue(standby.tick());assertEquals(true,second.callback(job,manifest,token).get("authorized"));second.finish(job,manifest,"SUCCEEDED",false);var completed=second.callback(job,manifest,token);assertEquals(false,completed.get("authorized"));assertEquals("SUCCEEDED",completed.get("state"));assertTrue(second.active().isEmpty());
 }
 @Test void legacyOrAnotherReleaseDoesNotInheritAScopedReadCapability(){
  UUID old=UUID.randomUUID();String token="x".repeat(43);fence.reserve(old,manifest,1,bindings());assertEquals(401,assertThrows(ControlFailure.class,()->fence.callback(old,manifest,token)).status);fence.finish(old,manifest,"FAILED",false);
  UUID job=UUID.randomUUID();fence.reserve(job,manifest,1,bindings(),ClusterDeploymentFence.tokenHash("y".repeat(43)));assertEquals(401,assertThrows(ControlFailure.class,()->fence.callback(job,manifest,token)).status);assertEquals("ACTIVE",fence.verify(job,manifest,false).get("state"));assertTrue(fence.noDispatchProven(job,manifest));
 }
}
